let v143AssignBusy=false;window.v143AssignExisting=function(){if(v143AssignBusy)return alert('Assignment is already being saved. Please wait.');const no=document.getElementById('sj')?.value?.trim()?.toUpperCase()||'',emp=document.getElementById('se2')?.value||'',raw=document.getElementById('st2')?.value||'',mins=typeof parseWorkMinutes==='function'?parseWorkMinutes(raw):NaN;if(!no||no===H||!byNo(no))return alert('Search and select a valid Job Card first.');const tech=emp&&typeof user==='function'?user(emp):null;if(!tech||tech.role!=='Employee')return alert('Select a valid technician.');if(!Number.isFinite(mins)||mins<1)return alert('Enter valid allocated time.');const duplicate=(S().assign||[]).some(a=>a&&!a.cancelled&&!a.completed&&String(a.job).toUpperCase()===no&&String(a.emp)===String(emp));if(duplicate)return alert('This technician already has an active assignment for this Job Card.');if(typeof window.assignJobCore!=='function')return alert('Assignment service is unavailable. Please sync and try again.');v143AssignBusy=true;try{return window.assignJobCore(no,emp,mins)}finally{setTimeout(()=>{v143AssignBusy=false},800)}};
