let voiceRecognition=null,voiceListening=false;
function voiceBox(){return document.getElementById('v143VoiceStatus')}
function voiceStopVisible(show){voiceListening=!!show;const b=document.getElementById('v143VoiceStop');if(b)b.classList.toggle('hidden',!show)}
window.v143StopVoiceEntry=function(){const b=voiceBox();voiceStopVisible(false);if(b)b.textContent='Processing speech…';try{if(window.AndroidBridge?.stopNativeVoiceRecognition){window.AndroidBridge.stopNativeVoiceRecognition();return}}catch(_){}if(voiceRecognition){try{voiceRecognition.stop()}catch(_){}voiceRecognition=null}};
window.v143StartVoiceEntry=function(){pendingVoiceEntry=null;voiceStopVisible(true);const b=voiceBox();if(b){b.textContent='Listening... Say job card, vehicle, year, registration, technician and time.';b.classList.remove('hidden')}try{if(window.AndroidBridge&&typeof AndroidBridge.startNativeVoiceRecognition==='function'){AndroidBridge.startNativeVoiceRecognition();return}}catch(_){}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){voiceStopVisible(false);if(b)b.textContent='Voice recognition is not available on this device.';return}const r=new SR();voiceRecognition=r;r.lang='en-US';r.interimResults=false;r.continuous=false;r.onresult=e=>{const t=Array.from(e.results||[]).map(x=>x[0]?.transcript||'').join(' ').trim();window.v143ApplyVoiceEntry(t)};r.onerror=e=>{voiceStopVisible(false);voiceRecognition=null;if(b)b.textContent='Voice recognition error: '+(e.error||'try again')};r.onend=()=>{voiceStopVisible(false);voiceRecognition=null};try{r.start()}catch(_){voiceStopVisible(false);voiceRecognition=null;if(b)b.textContent='Voice recognition could not start.'}};
let pendingVoiceEntry=null;
function renderVoiceReview(){
 const b=voiceBox();if(!b||!pendingVoiceEntry)return;
 const p=pendingVoiceEntry,rows=[['Job Card',p.newNo],['Vehicle Make / Model',p.newVehicle],['Model Year',p.newYear],['Registration',p.newReg],['Technician',p.techName],['Time',p.st]];
 b.innerHTML='<div><b>Heard:</b> '+esc(p.raw)+'</div><div class="v143-voice-preview">'+rows.map(([label,value])=>'<span><b>'+esc(label)+':</b> '+esc(value||'Not identified')+'</span>').join('')+'</div><div class="v143-voice-review-actions"><button type="button" onclick="v143AcceptVoiceEntry()" aria-label="Accept voice details">✓ OK</button><button type="button" onclick="v143RejectVoiceEntry()" aria-label="Reject voice details">×</button></div>';
 b.classList.remove('hidden');
}
window.v143RejectVoiceEntry=function(){pendingVoiceEntry=null;const b=voiceBox();if(b){b.textContent='Voice details discarded. Quick Entry is unchanged.';b.classList.remove('hidden')}};
window.v143AcceptVoiceEntry=function(){
 const p=pendingVoiceEntry;if(!p)return;
 for(const id of ['newNo','newVehicle','newYear','newReg','st']){const e=document.getElementById(id);if(e&&p[id])e.value=p[id]}
 const tech=document.getElementById('se');if(tech&&p.se)tech.value=p.se;
 pendingVoiceEntry=null;const b=voiceBox();if(b){b.textContent='Voice details accepted. Check the fields before creating the Job Card.';b.classList.remove('hidden')}
};
window.v143ApplyVoiceEntry=function(text){
 voiceStopVisible(false);const raw=String(text||'').trim();if(!raw)return;
 const boundary='(?=\\s+(?:job\\s*card|jc|registration|reg|plate|vehicle|make|model|year|technician|tech|time|allocated)\\b|$)';
 const take=label=>{const m=raw.match(new RegExp('(?:^|\\s)(?:'+label+')\\s*(?:number|no|is|:)?\\s*([a-z0-9][a-z0-9\\s-]*?)'+boundary,'i'));return m?m[1].trim():''};
 const jc=((take('job\\s*card|jc').match(/^[a-z0-9-]+/i)||[])[0]||'').toUpperCase();
 const reg=take('registration|reg|plate').replace(/[^a-z0-9 -]/gi,'').toUpperCase();
 const yr=(raw.match(/\b(19\d{2}|20\d{2})\b/)||[])[1]||'';
 let vehicle=take('vehicle|make|model').replace(/\b(?:year|model)\s*(?:19\d{2}|20\d{2})\b/ig,'').trim();
 if(!vehicle){const makes=['Mercedes Benz','Land Rover','Range Rover','Toyota','Lexus','Nissan','Infiniti','Hyundai','Genesis','Honda','Kia','BYD','Changan','Jetour','MG','Geely','Subaru','Jaguar','Audi','BMW','Porsche','Lincoln','GMC','Chrysler','Jeep','Dodge','Chevrolet','Isuzu','Volvo','Scania','MAN','Mitsubishi','Shacman','Volkswagen'];const make=makes.find(x=>new RegExp('\\b'+x.replace(/ /g,'\\s*')+'\\b','i').test(raw));if(make){const from=raw.toLowerCase().indexOf(make.toLowerCase());vehicle=raw.slice(from).split(/\b(?:registration|reg|plate|year|job\s*card|jc|technician|tech|time|allocated|19\d{2}|20\d{2})\b/i)[0].trim()}}
 const norm=v=>String(v||'').toLowerCase().replace(/[^a-z0-9]+/g,'');
 const q=norm(raw),tech=U().filter(u=>u&&u.role==='Employee').sort((x,y)=>String(y.name||'').length-String(x.name||'').length).find(u=>u.name&&q.includes(norm(u.name)));
 const h=raw.match(/(\d+(?:\.\d+)?)\s*(?:hours?|hrs?)\b/i),m=raw.match(/(\d+)\s*(?:minutes?|mins?)\b/i),mins=h?Math.round(Number(h[1])*60)+(m?Number(m[1]):0):m?Number(m[1]):0;
 pendingVoiceEntry={raw,newNo:jc,newVehicle:vehicle,newYear:yr,newReg:reg,se:tech?.id||'',techName:tech?.name||'',st:mins>0?(Math.floor(mins/60)+':'+String(mins%60).padStart(2,'0')):''};
 renderVoiceReview();
};
